import { useRef, useState } from 'react'
import DATA from '../review-data.json'

// Why native review matters, from the score history. Every number is generated by
// review_scores.py from translation_quality.json, the scores kept for the bank the
// 2026-10-11 scan sent, and per row scores that reproduce both (verify_all 2f, 2g).
const REPO = 'https://github.com/IshKej/polyguard'
const LO = 0.7
const HI = 0.95
const x = (v) => `${((v - LO) / (HI - LO)) * 100}%`
const f3 = (v) => v.toFixed(3)
const f4 = (v) => v.toFixed(4)
const BEFORE = '#7a7d6b' // ordinal pair with ink, validated against the paper surface

function Tip({ tip }) {
  if (!tip) return null
  return (
    <div role="status" className="pointer-events-none absolute z-20 -translate-x-1/2 -translate-y-full rounded-md bg-ink px-3 py-2 text-sm text-paper shadow-lg"
      style={{ left: tip.x, top: tip.y - 8 }}>
      <div className="font-bold">{tip.value}</div>
      <div className="text-mute-ink">{tip.label}</div>
    </div>
  )
}

// One measure for one language: a ring before review, a dot after, a line between.
function Dumbbell({ label, before, after, onTip, onLeave }) {
  const lo = Math.min(before, after)
  const hi = Math.max(before, after)
  const text = `${label}: ${f3(before)} before review, ${f3(after)} after`
  return (
    <div
      tabIndex={0} role="img" aria-label={text}
      onPointerMove={(e) => onTip(e, label, before, after)} onFocus={(e) => onTip(e, label, before, after)}
      onPointerLeave={onLeave} onBlur={onLeave}
      className="relative h-7 outline-offset-2"
    >
      {[0.75, 0.8, 0.85, 0.9].map((v) => (
        <span key={v} aria-hidden="true" className="absolute inset-y-0 w-px bg-(--line)" style={{ left: x(v) }} />
      ))}
      <span aria-hidden="true" className="absolute top-1/2 h-0.5 -translate-y-1/2" style={{ left: x(lo), width: `calc(${x(hi)} - ${x(lo)})`, background: BEFORE }} />
      <span aria-hidden="true" className="absolute top-1/2 size-3 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 bg-(--bg)" style={{ left: x(before), borderColor: BEFORE }} />
      <span aria-hidden="true" className="absolute top-1/2 size-3 -translate-x-1/2 -translate-y-1/2 rounded-full bg-ink ring-2 ring-(--bg)" style={{ left: x(after) }} />
    </div>
  )
}

function Chart() {
  const [tip, setTip] = useState(null)
  const box = useRef(null)
  const onTip = (e, label, b, a) => {
    const r = box.current.getBoundingClientRect()
    const t = e.currentTarget.getBoundingClientRect()
    setTip({ x: t.left - r.left + ((a - LO) / (HI - LO)) * t.width, y: t.top - r.top,
      value: `${f4(b)} to ${f4(a)}`, label: `${label}, before and after review` })
  }
  return (
    <figure ref={box} className="relative" aria-labelledby="dumbbell-caption">
      <ul className="mb-3 flex flex-wrap gap-x-5 gap-y-1 text-[.8rem] text-(--mute)" aria-label="Key">
        <li><i className="mr-1.5 inline-block size-3 rounded-full border-2 align-[-1px]" style={{ borderColor: BEFORE }} />before review</li>
        <li><i className="mr-1.5 inline-block size-3 rounded-full bg-ink align-[-1px]" />after review</li>
      </ul>
      <div className="grid grid-cols-[6.5rem_minmax(0,1fr)] gap-x-3 sm:grid-cols-[9rem_minmax(0,1fr)]">
        <div />
        <div className="grid grid-cols-[minmax(0,1fr)_6.5rem] gap-2" aria-hidden="true">
          <div className="relative mb-1 h-4 text-[.75rem] text-(--mute)">
            {[0.75, 0.8, 0.85, 0.9].map((v) => (
              <span key={v} className="absolute -translate-x-1/2 tabular-nums" style={{ left: x(v) }}>{v.toFixed(2)}</span>
            ))}
          </div>
          <div className="text-right text-[.7rem] text-(--mute)">before → after</div>
        </div>
        {DATA.moved.map((m) => (
          <div key={m.code} className="contents">
            <div className="row-span-2 border-t border-(--line) pt-1.5">
              <div className="font-semibold">{m.name}</div>
              <div className="text-[.75rem] text-(--mute)">{m.rows_changed} rows changed{m.rows_held ? `, ${m.rows_held} held` : ''}</div>
            </div>
            <div className="border-t border-(--line) pt-1">
              <div className="text-[.7rem] text-(--mute)">mean of 21 rows</div>
              <div className="grid grid-cols-[minmax(0,1fr)_6.5rem] items-center gap-2">
                <Dumbbell label={`${m.name}, mean`} before={m.mean[0]} after={m.mean[1]} onTip={onTip} onLeave={() => setTip(null)} />
                <span className="text-right text-[.78rem] tabular-nums"><span className="text-(--mute)">{f4(m.mean[0])} →</span> <b>{f4(m.mean[1])}</b></span>
              </div>
            </div>
            <div className="pb-2">
              <div className="text-[.7rem] text-(--mute)">lowest row</div>
              <div className="grid grid-cols-[minmax(0,1fr)_6.5rem] items-center gap-2">
                <Dumbbell label={`${m.name}, lowest row`} before={m.lowest[0]} after={m.lowest[1]} onTip={onTip} onLeave={() => setTip(null)} />
                <span className="text-right text-[.78rem] tabular-nums"><span className="text-(--mute)">{f4(m.lowest[0])} →</span> <b>{f4(m.lowest[1])}</b></span>
              </div>
            </div>
          </div>
        ))}
      </div>
      <figcaption id="dumbbell-caption" className="mt-3 text-[.8rem] text-(--mute)">
        LaBSE similarity of each line to its English source (1 is identical meaning to the model). Before: the bank
        the 2026-10-11 scan sent, scored {DATA.scores_first_built}. After: today’s bank, scored {DATA.scores_rebuilt}{' '}
        with the same models. An automated proxy, not a validation.
      </figcaption>
      <Tip tip={tip} />
    </figure>
  )
}

export default function ReviewWhy({ onBack, onCoverage }) {
  const lt = DATA.moved.find((m) => m.code === 'lt')
  const fr = DATA.moved.find((m) => m.code === 'fr')
  const ex = lt?.biggest_drop
  const m = DATA.machine
  const changed = DATA.moved.flatMap((l) => l.rows.filter((r) => r.before !== r.after).map((r) => ({ ...r, lang: l.name })))
  return (
    <main>
      <section data-surface="ink" className="ink">
        <div className="mx-auto max-w-7xl px-5 pb-16 pt-28 sm:pb-20">
          <button type="button" onClick={onBack} className="caption mb-6 text-[.8rem] underline underline-offset-4">Back</button>
          <h1 className="display max-w-4xl text-[clamp(2.1rem,4.4vw,3.6rem)]">
            Native speakers corrected the lines, and the score went down.
          </h1>
          <p className="mt-7 max-w-2xl text-lg text-(--mute)">
            PolyGuard scores every translation automatically: a language identifier checks each line is in the right
            language, and LaBSE measures how close it is to the English. Those scores catch the wrong language and gross
            changes of meaning. They cannot tell whether a line sounds like something a speaker would write, or whether
            a speaker would read it as an instruction. A native speaker can.
          </p>
        </div>
      </section>

      <section data-surface="paper" className="paper">
        <div className="mx-auto grid max-w-7xl gap-12 px-5 py-16 sm:py-20 lg:grid-cols-[minmax(0,.8fr)_minmax(0,1.2fr)]">
          <div>
            <h2 className="display text-[clamp(1.6rem,3vw,2.3rem)]">What review did to the score</h2>
            <p className="mt-4 text-(--mute)">
              In every language where a native speaker’s corrections changed the bank since the scores were first
              computed, here is the score before and after. Lithuanian’s lowest line fell from {f3(lt.lowest[0])} to{' '}
              {f3(lt.lowest[1])}; Bulgarian’s average moved from {f3(DATA.moved.find((d) => d.code === 'bg').mean[0])} to{' '}
              {f3(DATA.moved.find((d) => d.code === 'bg').mean[1])}. The reviewers moved the wording toward what they
              would write (the Lithuanian reviewer found some lines too polite; the Portuguese edits made the vocabulary
              Brazilian and current), and that took it a little further from the English wording the score compares
              against.
            </p>
            {fr && (
              <p className="mt-4 text-[.9rem] text-(--mute)">
                French moved up slightly. Its reviewer pointed out mixed formality; the five control lines were then
                rewritten by the author, so that wording is the author’s, not the reviewer’s.
              </p>
            )}
            {DATA.reviewed_before_scores.length > 0 && (
              <p className="mt-4 text-[.9rem] text-(--mute)">
                {DATA.reviewed_before_scores.map((r) => r.name).join(', ')} were reviewed before the first scores were
                computed ({DATA.scores_first_built}), so there is no before score for them, and none is shown.
              </p>
            )}
          </div>
          <Chart />
        </div>
      </section>

      {ex && (
        <section data-surface="paper" className="paper border-t border-(--line)">
          <div className="mx-auto max-w-7xl px-5 py-16">
            <h2 className="display max-w-3xl text-[clamp(1.6rem,3vw,2.3rem)]">The line whose score fell most</h2>
            <p className="mt-3 max-w-2xl text-(--mute)">
              A harmless capability check in Lithuanian, which only asks the bot to write a reference code. The reviewer
              found some lines too polite, and here she turned a polite question into a plain request.
            </p>
            <dl className="mt-8 grid max-w-4xl gap-3 sm:grid-cols-[9rem_minmax(0,1fr)_6rem]">
              {[['English source', ex.text.english, null, 'en'], ['Before review', ex.text.before, ex.before, 'lt'], ['After review', ex.text.after, ex.after, 'lt']].map(([k, v, s, lang]) => (
                <div key={k} className="contents">
                  <dt className="pt-2 text-[.85rem] font-semibold">{k}</dt>
                  <dd lang={lang} className="rounded-md bg-(--card) px-3 py-2">{v}</dd>
                  <dd className="pt-2 text-[.85rem] tabular-nums text-(--mute)">{s == null ? '' : `score ${f3(s)}`}</dd>
                </div>
              ))}
            </dl>
            <p className="mt-6 max-w-2xl text-(--mute)">
              The score fell from {f3(ex.before)} to {f3(ex.after)}. The English is a question and the corrected
              Lithuanian is not, the kind of change a similarity score penalises. For a capability check, wording a
              speaker would actually use is what matters, so a lower score here does not count against the line.
            </p>
          </div>
        </section>
      )}

      <section data-surface="ink" className="ink">
        <div className="mx-auto max-w-7xl px-5 py-16 sm:py-20">
          <h2 className="display max-w-3xl text-[clamp(1.6rem,3vw,2.3rem)]">What this means for the results</h2>
          <div className="mt-6 grid max-w-5xl gap-6 md:grid-cols-3">
            <p className="text-(--mute)">
              Across the {m.n} machine translated languages the middle average score is {f3(m.median_mean)} and the
              lowest {f3(m.lowest_mean)}. Only {m.flagged.join(', ')} is flagged. On this score most of them look fine,
              and that is all it can say.
            </p>
            <p className="text-(--mute)">
              Translation quality is the biggest threat to a per language result: a garbled attack can fail for
              reasons that have nothing to do with the bot. So the score stays beside every rate as a warning sign, and
              a language’s rate is never read as a finding on the score alone.
            </p>
            <p className="text-(--mute)">
              Native review goes where a bad translation would do the most damage, the low resource languages first.
              Feedback received and integrated is not a validation, and no language is marked as reviewed in the bank.
            </p>
          </div>
          <div className="mt-10 flex flex-wrap gap-3">
            <button type="button" onClick={onCoverage} className="btn btn-solid whitespace-normal text-left">See review coverage for all 73 languages</button>
            <a href={`${REPO}/blob/main/docs/NATIVE_REVIEW.md`} target="_blank" rel="noopener" className="btn btn-line">The review log</a>
          </div>
        </div>
      </section>

      <section data-surface="paper" className="paper">
        <div className="mx-auto max-w-7xl px-5 py-12">
          <details>
            <summary className="cursor-pointer font-semibold">See the numbers</summary>
            <table className="mt-4 w-full max-w-3xl text-left text-[.875rem] tabular-nums">
              <caption className="sr-only">Score before and after native review, per language</caption>
              <thead><tr className="border-b border-ink"><th className="py-1.5">Language</th><th>Mean before</th><th>Mean after</th><th>Lowest before</th><th>Lowest after</th></tr></thead>
              <tbody>
                {DATA.moved.map((d) => (
                  <tr key={d.code} className="border-b border-(--line)"><td className="py-1.5">{d.name}</td><td>{f3(d.mean[0])}</td><td>{f3(d.mean[1])}</td><td>{f3(d.lowest[0])}</td><td>{f3(d.lowest[1])}</td></tr>
                ))}
              </tbody>
            </table>
            <table className="mt-6 w-full max-w-3xl text-left text-[.875rem] tabular-nums">
              <caption className="mb-2 text-left text-(--mute)">Every line whose score changed</caption>
              <thead><tr className="border-b border-ink"><th className="py-1.5">Line</th><th>Before</th><th>After</th></tr></thead>
              <tbody>
                {changed.map((r) => (
                  <tr key={r.id} className="border-b border-(--line)"><td className="py-1 font-mono text-[.8rem]">{r.id}</td><td>{f3(r.before)}</td><td>{f3(r.after)}</td></tr>
                ))}
              </tbody>
            </table>
            <p className="mt-4 max-w-3xl text-[.8rem] text-(--mute)">
              Banks: before <code>{DATA.before_bank.slice(0, 12)}</code>, after <code>{DATA.after_bank.slice(0, 12)}</code>.
              Sources: <code>translation_quality.json</code>, <code>results/local/2026-10-11/translation_quality-at-scan.json</code>,{' '}
              <code>review_row_scores.json</code>, built by <code>review_scores.py</code>.
            </p>
          </details>
        </div>
      </section>
    </main>
  )
}
